contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= amount, "not enough balance");
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;
        assert(address(this).balance == beforeThis + amount && address(c).balance == beforeC - amount);
    }

    receive() external payable {}
}

